 {Proof p(root/"outer-fence-after-raw");const auto outer=p.Step();p.Iteration(outer);const auto release=(root/"actual-cleanup-exit-release").string();assert(setenv("SUITECUT_ATTACHMENT_RETRY_CLEANUP_RELEASE",release.c_str(),1)==0);p.Begin(1,0,"P",(root/"absent-parent-scope").string());p.Until([&]{for(const auto& entry:fs::directory_iterator("/proc")){std::ifstream stat(entry.path()/"stat");std::string row;std::getline(stat,row);const auto close=row.rfind(')');if(close==std::string::npos)continue;std::istringstream fields(row.substr(close+2));char state=0;int64_t parent=0;fields>>state>>parent;if(parent!=getpid())continue;std::ifstream in(entry.path()/"cmdline",std::ios::binary);std::string text((std::istreambuf_iterator<char>(in)),{});if(text.find("--native-attachment-cleanup")!=std::string::npos)return true;}return false;});assert(p.files.Physical()==1);p.Raw();assert(p.steps.Receive(p.owner,outer,true,"\"\"",af::Now()));bool forwarded=false;std::optional<std::string> parent_error;p.files.FenceStep(p.owner,outer,[&](const auto& error){parent_error=error;forwarded=true;},af::Now());assert(!forwarded);assert(unsetenv("SUITECUT_ATTACHMENT_RETRY_CLEANUP_RELEASE")==0);{std::ofstream out(release);out<<"release actual cleanup child exit";assert(out.good());}p.Until([&]{return !p.files.Physical();});assert(forwarded&&!parent_error&&p.fatal.empty()&&p.ordinary.size()==1);++count;}
